"use strict";(self.webpackChunkciroh_docuhub=self.webpackChunkciroh_docuhub||[]).push([["83647"],{46537(e){e.exports=JSON.parse('{"id":"evaluation-testbeds","title":"Evaluation and Testbeds Working Group","description":"Clarifies what evaluation information is needed to support R2O and other uses of model and forecast evaluation, and promotes and improves the existing protocols, benchmark datasets, tools, and operational testbeds associated with evaluation.","leads":["Shaun Carney, RTI"],"reportsCollectionId":"","annual":{"period":"2025-2026","objectives":["Clarify evaluation information needed to support R2O.",["Work with the CIROH R2O team and OWP management to clarify what evaluation evidence will help inform decisions about whether new approaches should be moved into operations","Define a complete suite of evaluation-related information that would support R2O decisions","Produce a template or example \u201Cpitch deck\u201D for summarizing results for management using at least one newly developed method"],"Clarify, promote, and improve evaluation protocols, baseline datasets, evaluation tools, and operational testbeds.",["Define the evaluation components and how they fit together\u2014i.e., evaluation protocols (how to compare a new method), benchmark datasets (what to compare against), evaluation tools and metrics (e.g., TEEHR, FIMeval), operational testbeds (e.g., NRDS, CHPS in the cloud), and results communication","Map what exists: Document what is already available for each evaluation component, who maintains it, and where to find it","Raise awareness and support use: Raise awareness through speaker demos, and provide worked examples or quick-start guidance so researchers can apply each component","Collect feedback: Gather user feedback on barriers, usability, and gaps for each component","Prioritize improvements: Identify and prioritize improvements for future CIROH development (e.g., expanding protocols, collecting/developing new baseline datasets, improving tool usability, improving operational testbed integration)","Maintain the guidance: Maintain the Evaluation Guidance document as a living resource with a clear update process"],"Build community knowledge of evaluation approaches, applications, and testbeds.",["Hold a monthly speaker series focused on evaluation and testbed-related topics. Record and share the sessions, with short summaries of key takeaways.","Use speaker input to shape guidance updates, evaluation improvements, and the R2O process"]],"accomplishments":[],"products":[]}}')}}]);